let matchingTask=null;
function matchInWorker(records,spans){return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./recognition-worker.js',import.meta.url),{type:'module'});const finish=(error,result)=>{clearTimeout(timer);worker.terminate();matchingTask=null;error?reject(error):resolve(result);};const timer=setTimeout(()=>finish(Error('Analyse trop longue. Essayez un document moins volumineux.')),30000);matchingTask={cancel:()=>finish(Error('Analyse annulée.'))};worker.onmessage=e=>finish(e.data.error?Error(e.data.error):null,e.data.results);worker.onerror=()=>finish(Error('Le moteur local de reconnaissance n’a pas pu terminer.'));worker.postMessage({records,spans});});}
let recognition={state:'idle',results:[],pages:0,empty:[],message:''};
let loadEpoch=0;
function resetRecognition(){loadEpoch++;matchingTask?.cancel();recognition={state:'idle',results:[],pages:0,empty:[],message:''};}

