function demoRecords(){let v={...values};if(pay==='debit'){[84,85,86].forEach(k=>delete v[k]);Object.assign(v,{81:'59 · Prélèvement SEPA',82:'Prélèvement',89:'MANDAT-DEMO-01',90:'ICS-DEMO · Fictif',91:'FRXX COMPTE À DÉBITER · Fictif'});}if(pay==='card'){[84,85,86].forEach(k=>delete v[k]);Object.assign(v,{81:'48 · Carte bancaire',82:'Carte',87:'1234 · Numéro tronqué',88:'Camille Martin'});}return [...Object.entries(v).map(([id,value])=>({id:+id,value,group:'Démonstration',index:0})),...lineValues.flatMap((l,index)=>Object.entries(l).filter(([id])=>+id!==158).map(([id,value])=>({id:+id,value,group:'Ligne',index})))];}
let activeRecords=demoRecords();
function get(id,records=activeRecords,line){return records.find(r=>r.id===id&&(line===undefined?r.group!=='Ligne':r.group==='Ligne'&&r.index===line));}
function field(id,records=activeRecords,line){const r=get(id,records,line);if(!r)return '<span class="subtle">—</span>';const ix=activeRecords.indexOf(r);return `<button class="field" data-record="${ix}" aria-label="${esc(terms.get(id)?.label)} : ${esc(r.value)}, BT-${id}"><span>${esc(r.value)}</span><span class="bt">BT-${id}</span></button>`;}
function vl(id,label,records=activeRecords,line){if(!get(id,records,line))return '';return `<div class="value-line">${label?`<span class="value-label">${esc(label)}</span>`:''}${field(id,records,line)}</div>`;}
function block(title,ids){return `<section class="block"><h3 class="block-title">${title}</h3>${ids.map(([id,label])=>vl(id,label)).join('')}</section>`;}
function invoiceHTML(){const r=activeRecords;const lineIds=[...new Set(r.filter(x=>x.group==='Ligne').map(x=>x.index))];const present=(ids)=>ids.some(id=>get(id));const lineHTML=lineIds.map(i=>`<tr><td><strong>${field(153,r,i)}</strong>${get(154,r,i)?`<div class="line-detail">${field(154,r,i)}</div>`:''}${advanced?`<div class="line-detail">${[126,127,128,132,133,134,135,155,156,157,158,159,160,161].map(id=>vl(id,terms.get(id).label,r,i)).join('')}</div>`:''}</td><td>${field(129,r,i)}<br>${field(130,r,i)}</td><td>${field(146,r,i)}${advanced?`<div class="line-detail">${[147,148,149,150,136,137,138,139,140,141,142,143,144,145].map(id=>vl(id,terms.get(id).label,r,i)).join('')}</div>`:''}</td><td>${field(152,r,i)}${advanced?vl(151,'Catégorie',r,i):''}</td><td>${field(131,r,i)}</td></tr>`).join('');
 return `<article class="invoice ${tech?'technical':''}"><div class="invoice-head"><div><div class="invoice-kicker">${imported&&location.hash==='#import'?'REPRÉSENTATION RECONSTITUÉE':'EXEMPLE PÉDAGOGIQUE'}</div><div class="invoice-brand">${get(28)?field(28):field(27)}</div></div><div style="text-align:right"><div class="invoice-word">${get(3)?.value.startsWith('381')?'Avoir':'Facture'}</div>${vl(1)}${vl(3)}</div></div><div class="two">${block('Émetteur',[[27],[35],[36],[38],[37],[40],[30,'Identifiant légal'],[31,'TVA'],[43,'Contact']])}${block('Facturé à',[[44],[50],[51],[53],[52],[55],[47,'Identifiant légal'],[48,'TVA'],[49,'Adresse de facturation']])}</div><div class="invoice-info">${[[2,'Date d’émission'],[9,'Échéance'],[13,'Commande'],[5,'Devise'],[11,'Projet'],[12,'Contrat']].filter(([id])=>get(id)).map(([id,label])=>`<div><span class="value-label">${label}</span>${field(id)}</div>`).join('')}</div><div class="table-scroll"><table class="line-table"><thead><tr><th>Prestation ou article</th><th>Quantité</th><th>Prix net HT</th><th>TVA</th><th>Montant HT</th></tr></thead><tbody>${lineHTML||'<tr><td colspan="5">Aucune ligne interprétée par ce lecteur.</td></tr>'}</tbody></table></div><div class="summary"><div>${block('Paiement',[[82],[81,'Moyen'],[84,'Compte'],[85,'Titulaire'],[86,'BIC'],[87,'Carte'],[88,'Titulaire'],[89,'Mandat'],[90,'Créancier'],[91,'Compte débité'],[83,'Référence'],[20]])}</div><div class="totals">${[[106,'Total des lignes HT'],[107,'Remises globales'],[108,'Frais globaux'],[109,'Total HT'],[110,'TVA'],[112,'Total TTC'],[113,'Déjà payé'],[114,'Arrondi'],[115,'Net à payer']].filter(([id])=>get(id)).map(([id,label])=>`<div class="total-row ${id===115?'final':''}"><span>${label}</span>${field(id)}</div>`).join('')}</div></div>${present([116,117,118,119])?`<section class="block"><h3 class="block-title">Ventilation de TVA</h3><div class="table-scroll"><table class="line-table"><thead><tr><th>Catégorie</th><th>Base HT</th><th>Taux</th><th>TVA</th></tr></thead><tbody>${[...new Set(r.filter(x=>x.id===116).map(x=>x.index))].map(index=>'<tr>'+[118,116,119,117].map(id=>{const item=r.find(x=>x.id===id&&x.index===index);return '<td>'+(item?recordButton(item):'—')+'</td>';}).join('')+'</tr>').join('')}</tbody></table></div>${vl(120)}${vl(121)}</section>`:''}
 ${advanced?`<div class="advanced"><h3>Informations complémentaires</h3><div class="advanced-grid">${block('Références et période',[[10,'Réf. acheteur'],[14,'Commande vendeur'],[15,'Réception'],[16,'Expédition'],[17,'Lot'],[18,'Objet'],[19,'Imputation'],[25,'Facture antérieure'],[26,'Date antérieure'],[73,'Du'],[74,'Au']])}${block('Lieu de livraison',[[70],[71,'Site'],[75],[76],[165],[78],[77],[79],[80],[72,'Livré le']])}${block('Détails vendeur',[[29,'Code tiers'],[32,'Identifiant fiscal'],[33],[34,'Adresse électronique'],[39],[162],[41],[42]])}${block('Détails acheteur',[[45],[46,'Code tiers'],[54],[163],[56],[57],[58]])}${block('Remise globale',[[92,'Montant'],[93,'Base'],[94,'Pourcentage'],[95,'Catégorie'],[96,'Taux TVA'],[97],[98,'Motif codé']])}${block('Frais globaux',[[99,'Montant'],[100,'Base'],[101,'Pourcentage'],[102,'Catégorie'],[103,'Taux TVA'],[104],[105]])}${present([59,60,61])?block('Bénéficiaire du paiement',[[59],[60],[61]]):''}${present([62,63])?block('Représentant fiscal',[[62],[63],[64],[65],[164],[66],[67],[68],[69]]):''}${block('Justificatifs',[[122,'Référence'],[123],[124],[125]])}${block('Informations de traitement',[[23,'Processus'],[24,'Profil'],[6,'Devise TVA'],[111,'TVA comptable'],[7,'Exigibilité TVA'],[8,'Code exigibilité']])}</div></div>`:''}<div class="invoice-note">${vl(21,'Sujet de note')}${vl(22)}${location.hash==='#import'?'Les champs absents restent absents. Cette vue ne certifie ni la conformité du XML ni celle du document original.':'Données entièrement fictives • Identifiants et coordonnées non utilisables • Exemple de lecture, pas une facture à émettre.'}</div></article>`;
}
function recordButton(r){return `<button class="field" data-record="${activeRecords.indexOf(r)}"><span>${esc(r.value)}</span><span class="bt">BT-${r.id}</span></button>`;}
function title(eye,title,text,action=''){return `<div class="heading-row"><div><p class="eyebrow">${eye}</p><h1>${title}</h1><p class="intro">${text}</p></div>${action}</div>`;}
function toolbar(demo=true){return `<div class="toolbar"><div class="segmented" aria-label="Mode de lecture"><button data-mode="client" class="${!tech?'active':''}">Lecture client</button><button data-mode="tech" class="${tech?'active':''}">Repères techniques</button></div><div class="tools-right"><label><input type="checkbox" id="advanced" ${advanced?'checked':''}> Détails avancés</label>${demo?`<select id="pay" aria-label="Moyen de paiement"><option value="transfer" ${pay==='transfer'?'selected':''}>Virement SEPA</option><option value="debit" ${pay==='debit'?'selected':''}>Prélèvement</option><option value="card" ${pay==='card'?'selected':''}>Carte bancaire</option></select>`:''}</div></div>`;}
function demo(){activeRecords=demoRecords();main.innerHTML=title('LA FACTURE, DÉCODÉE','Chaque donnée a une histoire.','Cliquez sur une information de la facture pour découvrir son rôle et le BT qui lui correspond.',`<button class="button" id="print">↗ Imprimer le lisible</button>`)+toolbar()+`<div class="workspace">${invoiceHTML()}<aside class="rail"><div class="rail-card purple"><h3>Explorez votre première facture</h3><p>Un document familier. Des informations structurées derrière chaque ligne.</p><div class="step"><b>1</b><span>Cliquez sur une donnée de la facture.</span></div><div class="step"><b>2</b><span>Découvrez sa définition et ses liens.</span></div><div class="step"><b>3</b><span>Activez les repères BT pour aller plus loin.</span></div></div><div class="rail-card"><div class="rail-stat">${new Set(activeRecords.map(r=>r.id)).size}</div><div class="rail-caption">BT illustrés dans cet exemple</div><div class="rail-links"><button data-bt="49">↗ Adresse électronique ou e-mail ?</button><button data-bt="115">↗ Comment calculer le net à payer ?</button><button data-bt="151">↗ Catégorie ou taux de TVA ?</button></div></div><div class="rail-card"><h3>Une facture cohérente</h3><p>Tous les BT ne sont pas applicables simultanément. Le catalogue contient les 164 termes du socle, dont les cas conditionnels.</p><a href="#catalog" class="button">Ouvrir le référentiel →</a></div></aside></div>`;bindCommon();}
function bindCommon(){main.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>showField(activeRecords[+b.dataset.record]));main.querySelectorAll('[data-bt]').forEach(b=>b.onclick=()=>showField({id:+b.dataset.bt,value:get(+b.dataset.bt)?.value}));main.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{tech=b.dataset.mode==='tech';render();});if($('#advanced'))$('#advanced').onchange=e=>{advanced=e.target.checked;render();};if($('#pay'))$('#pay').onchange=e=>{pay=e.target.value;render();};if($('#print'))$('#print').onclick=()=>window.print();}
function showField(r){const t=terms.get(r.id);if(!t)return;lastFocus=document.activeElement;const links=[...new Set(relations.filter(g=>g.includes(r.id)).flat())].filter(n=>n!==r.id);let status=t.status.startsWith('O')?'Obligatoire dans le socle':t.status.startsWith('G')?'Requis si le groupe est présent':t.status.startsWith('C')?'Obligatoire sous condition':'Facultatif dans le socle';$('#dialogContent').innerHTML=`<span class="code-pill">BT-${r.id}</span><h2 id="dialogTitle">${esc(t.label)}</h2><p>${esc(t.category)} · ${esc(t.group)}</p>${r.value?`<div class="sample-value"><small>VALEUR ${r.path?'LUE DANS LE XML':'DE DÉMONSTRATION'}</small>${esc(r.value)}</div>`:''}<div class="detail-grid"><div><small>OBLIGATION DE BASE</small>${status}</div><div><small>CONDITION OU GROUPE</small>${esc(t.status)}</div></div><h3>À comprendre</h3><p>${esc(t.notes.replace(/\[S[\d–]+\]/g,''))}</p>${r.path?`<h3>Emplacement exact dans le fichier</h3><code>${esc(r.path)}</code>${Object.keys(r.attributes||{}).length?`<p>Attributs : ${esc(JSON.stringify(r.attributes))}</p>`:''}`:'<p>Le BT décrit le sens de la donnée. La balise XML dépend de la syntaxe UBL ou CII et du profil retenu.</p>'}${links.length?`<h3>Données liées</h3><div class="related">${links.map(id=>`<button data-related="${id}">BT-${id}</button>`).join('')}</div>`:''}<p class="hint">« Facultatif dans le socle » ne signifie pas « facultatif en France ». Appliquer les règles du profil et du cas d’usage concernés.</p><a class="subtle" href="https://docs.peppol.eu/poacc/billing/3.0/rules/ubl-tc434/" target="_blank" rel="noopener">Consulter les règles du socle ↗</a>`;$('#dialogContent').querySelectorAll('[data-related]').forEach(b=>b.onclick=()=>showField({id:+b.dataset.related,value:get(+b.dataset.related)?.value}));if(!dialog.open)dialog.showModal();}
$('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close();}});dialog.addEventListener('close',()=>lastFocus?.focus());
function catalogPage(){main.innerHTML=title('LE RÉFÉRENTIEL','Retrouvez le sens de chaque BT.','164 termes métier du socle EN 16931, regroupés par usage. BT-4 n’est pas attribué. Les extensions françaises ne sont pas incluses.')+`<div class="filters"><input class="search" id="search" placeholder="Rechercher un BT, une donnée, un mot-clé…" aria-label="Rechercher un BT"><select id="catFilter" aria-label="Catégorie"><option value="">Toutes les catégories</option>${[...new Set(catalog.map(x=>x.category))].map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="statusFilter" aria-label="Obligation"><option value="">Toutes les obligations</option><option value="O">Obligatoire</option><option value="G">Requis dans le groupe</option><option value="C">Conditionnel</option><option value="F">Facultatif dans le socle</option></select></div><p class="subtle" id="resultCount"></p><div class="catalog-grid" id="catalogResults"></div>`;const update=()=>{const q=$('#search').value.toLowerCase().trim(),cat=$('#catFilter').value,status=$('#statusFilter').value;const result=catalog.filter(t=>(!cat||t.category===cat)&&(!status||t.status.startsWith(status))&&(!q||(`bt-${t.id} ${t.label} ${t.category}`).toLowerCase().includes(q)));$('#resultCount').textContent=`${result.length} terme${result.length>1?'s':''}`;$('#catalogResults').innerHTML=result.length?result.map(t=>`<button class="bt-card" data-bt="${t.id}"><span class="code-pill">BT-${t.id}</span><strong>${esc(t.label)}</strong><small>${esc(t.status)} · ${esc(t.category)}</small></button>`).join(''):'<div class="empty">Aucun BT ne correspond à cette recherche.</div>';bindCommon();};$('#search').oninput=update;$('#catFilter').onchange=update;$('#statusFilter').onchange=update;update();}
function importPage(){if(imported)activeRecords=imported.records;main.innerHTML=title('VOS DOCUMENTS','Du fichier à la facture lisible.','Importez un XML UBL ou CII pour explorer ses données. Un PDF Factur-X permet aussi de rapprocher les BT de son visuel original.')+`<div class="upload-panel"><div class="upload-icon">↥</div><h2>Ouvrir une facture</h2><p>Le traitement reste dans votre navigateur. Aucun fichier n’est envoyé ni conservé sur un serveur.</p><div class="upload-actions"><label class="button primary" tabindex="0">Choisir un XML<input id="xmlFile" type="file" accept=".xml,application/xml,text/xml"></label><label class="button" tabindex="0">Choisir un PDF Factur-X<input id="pdfFile" type="file" accept=".pdf,application/pdf"></label><button class="button" id="sampleUbl">Essayer un XML UBL</button><button class="button" id="sampleCii">Essayer un XML CII</button><button class="button" id="clearImport">Effacer la session</button></div><p class="subtle">XML : 12 Mo maximum · PDF : 25 Mo maximum · Lecture expérimentale, sans validation XSD ou Schematron.</p></div><div id="fileStatus" role="status"></div><div id="importBody"></div>`;
 $('#xmlFile').onchange=e=>handleXML(e.target.files[0]);$('#pdfFile').onchange=e=>handlePDF(e.target.files[0]);$('#sampleUbl').onclick=async()=>{await pdf?.loadingTask.destroy();pdf=null;annotations=[];resetRecognition();await loadXml(await fetch('sample-ubl.xml').then(r=>r.text()),'Exemple UBL');};$('#sampleCii').onclick=async()=>{await pdf?.loadingTask.destroy();pdf=null;annotations=[];resetRecognition();await loadXml(await fetch('sample-cii.xml').then(r=>r.text()),'Exemple CII');};if($('#clearImport'))$('#clearImport').onclick=()=>{resetRecognition();imported=null;activeRecords=[];pdf?.loadingTask.destroy();pdf=null;annotations=[];selectedRecord=null;lastFocus=null;dialog.close();$('#dialogContent').replaceChildren();window.location.reload();};main.querySelectorAll('.upload-actions label').forEach(l=>l.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();l.querySelector('input').click();}});renderImportBody();}
function error(msg){if(!$('#fileStatus'))return;$('#fileStatus').innerHTML=`<div class="error">${esc(msg)}</div>`;}
async function handleXML(file){if(!file)return;if(file.size>12*1024*1024)return error('Le XML dépasse 12 Mo.');pdf?.loadingTask.destroy();pdf=null;annotations=[];resetRecognition();selectedRecord=null;try{await loadXml(await file.text(),file.name);}catch(e){imported=null;renderImportBody();error(e.message);}}
async function loadXml(xml,name){try{const parsed=parseInvoice(xml);imported={...parsed,fileName:name};activeRecords=imported.records;renderImportBody();$('#fileStatus').textContent='';}catch(e){imported=null;renderImportBody();error(e.message);}}
function renderImportBody(){const container=$('#importBody');if(!container)return;if(!imported&&!pdf){container.innerHTML=`<div class="guide-grid"><section class="guide-block"><h3>UBL et CII</h3><p>Le lecteur reconstruit un lisible à partir des champs reconnus, avec leurs chemins XML. Les données non interprétées restent consultables. Aucun montant manquant n’est inventé.</p></section><section class="guide-block"><h3>Factur-X et son PDF</h3><p>Le texte du PDF est rapproché automatiquement des valeurs XML. Tous les emplacements reconnus sont repérés automatiquement, y compris les occurrences répétées. Un placement manuel reste possible. Les PDF sans texte nécessitent un OCR non inclus.</p></section></div>`;return;}
 let html='';if(imported){activeRecords=imported.records;html=`<div class="import-meta"><span>${esc(imported.fileName)}</span><span><strong>${imported.syntax}</strong></span><span><strong>${new Set(imported.records.map(r=>r.id)).size}</strong> BT reconnus</span><span><strong>${imported.unknown.length}</strong> éléments non interprétés</span></div><p class="hint">Vue partielle possible : les champs reconnus sont affichés ci-dessous. L’outil ne valide pas la conformité française et ne couvre pas toutes les extensions.</p>`;}
 if(pdf){html+=`<div class="import-header"><h2>Associer les BT au visuel</h2><button class="button" id="exportAnnotations">Exporter les repères JSON</button></div><p class="subtle">Sélectionnez une donnée à droite, puis cliquez sur sa position dans le PDF. Les repères sont placés automatiquement sans confirmation ; les associations possibles sont indiquées. Le surlignage encadre le fragment de texte trouvé, parfois avec son libellé. Les repères restent dans cette session. Cliquer sur un repère ouvre sa fiche ; le bouton × de la liste le retire.</p><div id="recognitionPanel" class="recognition-panel" aria-live="polite"></div><div class="pdf-actions"><button class="button" id="recognize">Relancer la reconnaissance</button><button class="button" id="prevPage">←</button><span id="pageLabel"></span><button class="button" id="nextPage">→</button><span class="subtle" id="selectedLabel">Choisissez un BT dans la liste.</span></div><div class="pdf-layout"><div class="pdf-paper"><canvas id="pdfCanvas"></canvas><div class="pdf-overlay" id="pdfOverlay"></div></div><aside class="pdf-list" id="pdfList"></aside></div>`;}
 if(imported){html+=`<div class="import-header"><h2>Lisible reconstitué</h2><button class="button" id="print">↗ Imprimer</button></div>${toolbar(false)}${invoiceHTML()}<details><summary>Toutes les occurrences BT reconnues (${imported.records.length})</summary><div class="catalog-grid">${imported.records.map((r,i)=>`<button class="bt-card" data-record="${i}"><span class="code-pill">BT-${r.id}</span><strong>${esc(terms.get(r.id)?.label)}</strong><span>${esc(r.value)}</span><small>${esc(r.group)} ${r.index+1}</small></button>`).join('')}</div></details><details><summary>Éléments XML non interprétés (${imported.unknown.length})</summary><p class="subtle">Cette liste peut contenir des éléments techniques, des données d’extension ou des champs non encore mappés. Elle n’est pas une liste d’erreurs.</p><div class="unmapped">${imported.unknown.map(u=>`<p><code>${esc(u.path)}</code>${esc(u.value)}</p>`).join('')||'<p>Aucun élément terminal non interprété.</p>'}</div></details>`;}
 container.innerHTML=html;bindCommon();if(pdf){$('#prevPage').onclick=()=>{if(pdfPage>1&&!pdfBusy){pdfPage--;drawPDF();}};$('#nextPage').onclick=()=>{if(pdfPage<pdf.numPages&&!pdfBusy){pdfPage++;drawPDF();}};$('#exportAnnotations').onclick=()=>download('reperes-bt.json',JSON.stringify({document:imported?.fileName||'PDF sans XML reconnu',method:'Placement automatique de toutes les correspondances textuelles, sans confirmation ; associations heuristiques',recognition:{state:recognition.state,pages:recognition.pages,pagesWithoutText:recognition.empty,results:recognition.results},pages:pdf.numPages,annotations:annotations.map(a=>({...a,bt:imported?.records[a.record]?.id,value:imported?.records[a.record]?.value}))},null,2),'application/json');$('#recognize').onclick=()=>recognizePDF();renderRecognitionPanel();renderPdfList();drawPDF();}}
async function handlePDF(file){if(!file)return;if(file.size>25*1024*1024)return error('Le PDF dépasse 25 Mo.');$('#fileStatus').textContent='Lecture du PDF et recherche du XML embarqué…';try{const lib=await import('./vendor/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.min.mjs',import.meta.url).href;const fresh=await lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,enableScripting:false,useWasm:false,verbosity:0,stopAtErrors:true}).promise;if(fresh.numPages>100){await fresh.loadingTask.destroy();throw Error('Ce lecteur est limité à 100 pages.');}pdf?.loadingTask.destroy();pdf=fresh;pdfPage=1;annotations=[];resetRecognition();selectedRecord=null;imported=null;const attachments=await pdf.getAttachments();const xmls=Array.from(attachments||[],([id,a])=>({...a,attachmentId:id})).filter(a=>/\.xml$/i.test(a.filename));const preferred=xmls.filter(a=>/^(factur-x|zugferd-invoice)\.xml$/i.test(a.filename));const candidates=preferred.length?preferred:xmls;if(candidates.length===1){const content=await pdf.getAttachmentContent(candidates[0].attachmentId);if(!content||content.byteLength>12*1024*1024)throw Error('XML embarqué absent ou supérieur à 12 Mo.');const parsed=parseInvoice(new TextDecoder().decode(content));if(parsed.syntax!=='CII')throw Error('Le XML embarqué n’est pas un CII Factur-X reconnu.');imported={...parsed,fileName:file.name+' → '+candidates[0].filename};activeRecords=imported.records;$('#fileStatus').textContent='XML CII extrait. Reconnaissance automatique du texte en cours…';}else $('#fileStatus').textContent=candidates.length?'Plusieurs XML sont présents : sélection automatique impossible. Le PDF reste visible.':'Aucun XML embarqué reconnu. Le PDF est visible, mais aucun BT ne peut être extrait.';renderImportBody();if(imported&&pdf)await recognizePDF();}catch(e){error('Lecture interrompue : '+e.message);renderImportBody();}}

async function drawPDF(){if(pdfBusy)return;pdfBusy=true;try{const page=await pdf.getPage(pdfPage);const v=page.getViewport({scale:1.5});const canvas=$('#pdfCanvas');if(!canvas)return;canvas.width=v.width;canvas.height=v.height;await page.render({canvasContext:canvas.getContext('2d'),viewport:v}).promise;$('#pageLabel').textContent=`Page ${pdfPage} / ${pdf.numPages}`;$('#prevPage').disabled=pdfPage===1;$('#nextPage').disabled=pdfPage===pdf.numPages;renderOverlays();$('#pdfOverlay').onclick=e=>{if(e.target!==$('#pdfOverlay')||selectedRecord===null||!imported)return;const bounds=e.currentTarget.getBoundingClientRect();const x=Math.min(.85,Math.max(0,(e.clientX-bounds.left)/bounds.width));const y=Math.min(.97,Math.max(0,(e.clientY-bounds.top)/bounds.height));annotations.push({record:selectedRecord,page:pdfPage,x,y,width:.15,height:.03,origin:'manual',association:'manual'});renderOverlays();renderPdfList();};}catch(e){error('Impossible de rendre la page PDF : '+e.message);}finally{pdfBusy=false;}}
function renderOverlays(){const overlay=$('#pdfOverlay');if(!overlay||!imported)return;const groups=groupPlacements(annotations,pdfPage);overlay.innerHTML=groups.map((g,i)=>{const ids=[...new Set(g.entries.map(e=>imported.records[e.annotation.record].id))];const possible=g.entries.some(e=>e.annotation.association==='possible');return `<button class="annotation ${possible?'possible':'automatic'}" title="${esc(ids.map(id=>'BT-'+id).join(', '))} · ${g.entries.length} association(s)${possible?' possible(s)':''}" data-overlay-group="${i}" style="left:${g.x*100}%;top:${g.y*100}%;width:${Math.max(g.width,.025)*100}%;height:${Math.max(g.height,.012)*100}%"><span>${ids.map(id=>'BT-'+id).join(' · ')}</span></button>`;}).join('');overlay.querySelectorAll('[data-overlay-group]').forEach(b=>b.onclick=e=>{e.stopPropagation();const g=groups[+b.dataset.overlayGroup];if(g.entries.length===1){showField(imported.records[g.entries[0].annotation.record]);return;}lastFocus=document.activeElement;$('#dialogContent').innerHTML=`<span class="code-pill">${g.entries.length} associations sur ce texte</span><h2 id="dialogTitle">Données associées à cet emplacement</h2><p>Cette valeur correspond à plusieurs données XML. Les repères ont été placés automatiquement ; aucune confirmation n’est nécessaire. Cliquez sur un BT pour en lire la définition.</p><div class="related">${g.entries.map((e,j)=>{const r=imported.records[e.annotation.record];return `<button data-inspect="${j}">BT-${r.id} · ${esc(r.group)} ${r.index+1}</button>`;}).join('')}</div>`;$('#dialogContent').querySelectorAll('[data-inspect]').forEach(x=>x.onclick=()=>showField(imported.records[g.entries[+x.dataset.inspect].annotation.record]));dialog.showModal();});}

function renderRecognitionPanel(){const el=$('#recognitionPanel');if(!el)return;const counts={unique:0,ambiguous:0,missing:0,unsupported:0};recognition.results.forEach(r=>counts[r.status]++);el.innerHTML=recognition.state==='running'?`<b>Analyse du texte en cours</b> · ${recognition.pages} / ${pdf?.numPages||0} pages` : recognition.state==='done'?`<b>Reconnaissance terminée</b><div class="recognition-stats"><span>${annotations.length} repères placés</span><span>${counts.ambiguous} valeurs répétées ou partagées</span><span>${counts.missing} non trouvées</span><span>${counts.unsupported} codes à vérifier manuellement</span></div><small>La correspondance textuelle ne prouve pas le rôle métier. Tous les emplacements trouvés sont annotés sans confirmation. Une même valeur peut porter plusieurs BT possibles.${recognition.empty.length?' Pages sans texte exploitable : '+recognition.empty.join(', ')+'. OCR nécessaire, non inclus.':''}</small>`:recognition.state==='error'?`<b>Analyse interrompue</b> · ${esc(recognition.message)}`:'La reconnaissance démarre automatiquement après extraction du XML. Elle utilise la couche texte du PDF, sans envoi de fichier.';if($('#recognize'))$('#recognize').disabled=recognition.state==='running'||!imported;}
async function recognizePDF(){if(!pdf||!imported||recognition.state==='running')return;const current=pdf,source=imported,epoch=loadEpoch;recognition={state:'running',results:[],pages:0,empty:[],message:''};renderRecognitionPanel();try{const spans=[];for(let page=1;page<=current.numPages;page++){if(current!==pdf||source!==imported||epoch!==loadEpoch)return;const p=await current.getPage(page);const content=await p.getTextContent();const items=textSpans(content,p.getViewport({scale:1}),page);if(!items.length)recognition.empty.push(page);spans.push(...items);if(spans.length>80000)throw Error('Document trop dense pour cette analyse locale. Limite de 80 000 fragments de texte.');recognition.pages=page;renderRecognitionPanel();await new Promise(r=>setTimeout(r,0));}if(current!==pdf||source!==imported||epoch!==loadEpoch)return;const results=await matchInWorker(source.records,spans);if(current!==pdf||source!==imported||epoch!==loadEpoch)return;recognition.results=results;recognition.state='done';annotations=placeMatches(recognition.results,annotations);renderRecognitionPanel();renderPdfList();renderOverlays();if($('#fileStatus'))$('#fileStatus').textContent='Texte analysé. Tous les emplacements reconnus sont repérés automatiquement, sans confirmation.';}catch(e){if(current!==pdf||epoch!==loadEpoch)return;recognition.state='error';recognition.message=e.message;renderRecognitionPanel();}}
function renderPdfList(){const el=$('#pdfList');if(!el)return;if(!imported){el.innerHTML='<p class="subtle">Pas de données BT extraites du PDF.</p>';return;}el.innerHTML=imported.records.map((r,i)=>{const marks=annotations.map((a,j)=>({...a,arrayIndex:j})).filter(a=>a.record===i),result=recognition.results[i];const status=marks.length?`${marks.length} emplacement(s) repéré(s)${result?.shared?' · valeur partagée':''}`:result?.status==='missing'?'Texte non trouvé':result?.status==='unsupported'?'Code court ou technique : placement manuel':'Non localisé';return `<div class="match-item"><button data-pick="${i}" class="${selectedRecord===i?'selected':''}"><b>BT-${r.id}</b> · ${esc(terms.get(r.id)?.label)}<br>${esc(r.value)}<br><small>${esc(r.group)} · occurrence ${r.index+1}</small><br><span class="state">${status}</span></button>${marks.length?`<details ${marks.length<=3?'open':''}><summary>Voir les ${marks.length} emplacements</summary>${marks.map((a,j)=>`<div class="match-controls"><button data-locate-mark="${a.arrayIndex}">${j+1} · Page ${a.page} · ${Math.round(a.y*100)} %</button><button data-remove-mark="${a.arrayIndex}" aria-label="Retirer cet emplacement BT-${r.id}">Retirer</button></div>`).join('')}</details>`:''}</div>`;}).join('');el.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{selectedRecord=+b.dataset.pick;renderPdfList();$('#selectedLabel').textContent=`BT-${imported.records[selectedRecord].id} sélectionné : cliquez sur le PDF pour ajouter un emplacement.`;});el.querySelectorAll('[data-remove-mark]').forEach(b=>b.onclick=()=>{annotations.splice(+b.dataset.removeMark,1);renderPdfList();renderOverlays();renderRecognitionPanel();});el.querySelectorAll('[data-locate-mark]').forEach(b=>b.onclick=()=>{if(pdfBusy)return;pdfPage=annotations[+b.dataset.locateMark].page;drawPDF();});}

function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function guide(){main.innerHTML=title('COMPRENDRE AVANT DE PARAMÉTRER','Un vocabulaire commun.','Les BT décrivent les informations. Les BG les regroupent. Les règles métier fixent leurs liens et leurs conditions.')+`<div class="guide-grid"><section class="guide-block"><h3>Pour présenter à un client</h3><p>Commencez par la facture interactive en lecture client. Montrez l’émetteur, le destinataire, la commande, les lignes, puis le net à payer. Ouvrez une fiche seulement lorsqu’une question se pose.</p><p>Les détails avancés regroupent les adresses, références, frais et données de traitement. Les repères techniques rendent les codes BT visibles.</p></section><section class="guide-block"><h3>Obligatoire ne signifie pas toujours présent</h3><p><b>O</b> : obligatoire dans la facture.<br><b>G</b> : requis dans le groupe si ce groupe existe.<br><b>C</b> : conditionnel.<br><b>F</b> : facultatif dans le socle européen.</p><p>Un champ peut devenir obligatoire en France ou pour un cas d’usage. Une cardinalité 1..1 dans un groupe facultatif ne rend pas ce groupe obligatoire.</p></section><section class="guide-block"><h3>Les montants se recoupent</h3><p>BT-109 = BT-106 − BT-107 + BT-108<br>BT-110 = somme des BT-117<br>BT-112 = BT-109 + BT-110<br>BT-115 = BT-112 − BT-113 + BT-114</p><p>Appliquer les règles d’arrondi du profil. Les remises de ligne sont déjà intégrées dans BT-131.</p></section><section class="guide-block"><h3>Un BT, plusieurs écritures XML</h3><p>Le nom du vendeur est BT-27. En UBL il se trouve sous AccountingSupplierParty / Party / PartyLegalEntity / RegistrationName ; en CII, sous ApplicableHeaderTradeAgreement / SellerTradeParty / Name.</p><p>Les fiches des fichiers importés montrent le chemin réellement lu et les attributs présents.</p></section><section class="guide-block"><h3>Le périmètre de cette première version</h3><p>Le référentiel recense les 164 BT principaux, sans BT-4. Le lecteur prend en charge une sélection étendue de champs UBL et CII ; les extensions et certains cas restent non interprétés. Le lisible reconstitué ne remplace pas l’original.</p><p>Pas de contrôle XSD, Schematron, fiscal ou de conformité PDF/A. Les éléments non interprétés restent accessibles. Les fichiers restent en mémoire jusqu’à effacement ou fermeture.</p></section><section class="guide-block"><h3>Factur-X et la preuve visuelle</h3><p>Le PDF et le XML peuvent présenter une même information différemment. Le XML ne donne généralement pas ses coordonnées graphiques. Un montant répété ne permet pas un rapprochement certain.</p><p>Cette version extrait le XML embarqué et recherche ses valeurs dans le texte du PDF, sur toutes les pages. Toutes les correspondances sont placées automatiquement, y compris les répétitions du même BT. Les valeurs partagées sont signalées comme associations possibles. Les codes courts restent manuels. Aucune confirmation n’est demandée. Le placement reste heuristique et ne constitue pas une certification. L’export JSON conserve les repères ; leur réimport n’est pas encore proposé.</p></section><section class="guide-block"><h3>Sources de référence</h3><p><a href="https://www.impots.gouv.fr/specifications-externes-b2b" target="_blank" rel="noopener">DGFiP — Spécifications et normes ↗</a></p><p><a href="https://fnfe-mpe.org/ressources/" target="_blank" rel="noopener">FNFE-MPE — XP Z12-012, annexes et composants ↗</a></p><p><a href="https://docs.peppol.eu/poacc/billing/3.0/rules/ubl-tc434/" target="_blank" rel="noopener">Règles EN 16931 appliquées à UBL ↗</a></p><p>Les règles propres à Peppol ne sont pas automatiquement les règles françaises. Référentiel pédagogique daté d’octobre 2026.</p></section><section class="guide-block"><h3>Pour la suite</h3><p>Étendre les mappings sur vos fichiers de recette, ajouter la validation par profil, puis enrichir les règles de rapprochement visuel. Pour une image scannée, un traitement OCR spécifique serait nécessaire.</p><p>Les imports expérimentaux sont distincts de la facture de démonstration : aucune valeur fictive ne complète un fichier importé.</p></section></div>`;}
function render(){const route=location.hash.slice(1)||'demo';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route));$('#breadcrumb').textContent='Explorer / '+({demo:'Facture interactive',import:'Importer une facture',catalog:'Référentiel des BT',guide:'Comprendre les données'}[route]||'Facture interactive');({demo,import:importPage,catalog:catalogPage,guide}[route]||demo)();}
window.addEventListener('hashchange',render);render();
